ship out(size(200), sendspace((-1,0,0)..(0,-1,0)..(1,0,0),ArcArrow));
draw((-1,0,0)..(0,-1,0)..(1,0,0),linewidth(1.5));
draw((-1.75,0,0)--(1.75,0,0),dotted);
label("Large Cone",(0,0,0.5));
